#!/usr/bin/env python3
"""Descriptive presence check authorized after independent source acceptance.
Reads only id and healthcare witness, never assignments or hierarchy.
"""
from pathlib import Path
import pandas as pd,json,hashlib,datetime
H=Path(__file__).resolve().parent;R=H.parent;M=R/'model/output_word_ci_2021_baseline'
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
paths={'source_review_json':H/'holdout2021_independent_source_review.json','source_review_csv':H/'holdout2021_independent_source_review.csv','model_freeze_receipt':H/'holdout2021_model_freeze_receipt.json','model_manifest':M/'output_manifest.json','own_mass_components':M/'own_mass_components.parquet','code':Path(__file__)}
before={k:sha(v) for k,v in paths.items()};freeze=json.loads(paths['model_freeze_receipt'].read_text());assert before['model_manifest']==freeze['model_manifest_sha256']
manifest=json.loads(paths['model_manifest'].read_text());assert before['own_mass_components']==manifest['files']['own_mass_components.parquet']['sha256']
r=pd.read_csv(paths['source_review_csv']);review=json.loads(paths['source_review_json'].read_text());assert review['source_unchanged_verified'] and review['review_csv_sha256']==before['source_review_csv']
r=r[~r.is_household_unit].copy();assert len(r)==10 and r.provider_location_literal_accepted.all() and r.same_resolved_origin_destination.all()
# Location witness checks10 real provider records including the one with zero
# attachments; it does NOT treat that zero as absence/presence of an attachment.
rows=[]
for uid,g in r.groupby('destination_id',sort=True):
 rows.append({'id':uid,'name':g.destination_axis_name.iloc[0],'type':g.destination_axis_type.iloc[0],'region':g.destination_axis_region.iloc[0],'n_independently_verified_real_provider_rows':len(g),'raw_source_row_indices':';'.join(g.raw_source_row_index.astype(str)),'official_pdf_pages':';'.join(g.official_pdf_page.astype(str)),'official_provider_names':' | '.join(g.provider_name_raw),'official_source_locators':' | '.join(g.official_locator),'official_zero_attached_population_present':bool(g.attached_population_raw.eq(0).any()),'whole_NP_all_residents_verified':False})
s=pd.DataFrame(rows);m=pd.read_parquet(paths['own_mass_components'],columns=['id','physical_healthcare_positive_witness']);assert m.id.is_unique
out=s.merge(m,on='id',how='left',validate='one_to_one',indicator=True);out['id_found_in_frozen_mass']=out['_merge'].eq('both');out=out.drop(columns='_merge');assert len(out)==9 and out.id_found_in_frozen_mass.all()
out['comparison_kind']='descriptive_source_positive_location_witness_observability_not_assignment_agreement';out.to_csv(H/'holdout2021_healthcare_presence_review.csv',index=False)
obs=out.physical_healthcare_positive_witness;pos=int(obs.eq(True).sum());neg=int(obs.eq(False).sum());unknown=int(obs.isna().sum());after={k:sha(v) for k,v in paths.items()};assert before==after
receipt={'status':'COMPUTED_DESCRIPTIVE_POSITIVE_LOCATION_WITNESS_COVERAGE','computed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'author':'Codex /root/agro_demographic_context','authorization':'Parent /root instruction after independent source-only review:10 independently accepted real medical-provider records, deduplicated exact NP IDs; compare only physical_healthcare_positive_witness, no assignment agreement.','source_independently_reviewed_real_provider_rows':10,'unique_source_positive_provider_NP_locations':9,'present_physical_healthcare_positive_witness':pos,'false_witness_not_evidence_of_absent_healthcare':neg,'unknown_or_missing_witness':unknown,'descriptive_fraction_on_this_selected_subset':pos/len(out),'deduplication':'Exact accepted destination NP-ID; Kondrovo polyclinic and child consultation collapse to one NP. No household rows.','interpretation':'2 of9 nonrepresentatively selected source-confirmed healthcare locations have a positive frozen OSM2021 NP-level healthcare witness. False means this model source lacks a positive witness, not that the medical provider did not exist. This checks observability of healthcare presence in this subset; it is not national recall, provider-specific record match, service capability, attachment agreement, observed trips or intersettlement validation. The official decree date and OSM2021 observation date may differ.','primary_external_holdout_result':'No accepted intersettlement comparable pairs; no assignment metric computed. This is corpus ineligibility for that test, neither0%accuracy nor a model failure.','columns_read_from_model':['id','physical_healthcare_positive_witness'],'assignment_tables_read':False,'model_assignment_agreement_computed':False,'model_or_parameters_changed':False,'source_sha256_before':before,'source_sha256_after':after,'source_unchanged_verified':before==after,'output_csv_sha256':sha(H/'holdout2021_healthcare_presence_review.csv')}
(H/'holdout2021_healthcare_presence_review.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:receipt[k] for k in ['status','unique_source_positive_provider_NP_locations','present_physical_healthcare_positive_witness','false_witness_not_evidence_of_absent_healthcare','descriptive_fraction_on_this_selected_subset']}))
